@import "@fontsource-variable/host-grotesk";
@import "@fontsource-variable/source-code-pro";

/* Light (faithful): pale steel paper #f2f6fa ("sunlight"), deep navy ink #162029, one sonar
   lime #acff24 for every primary button and the join card. Hairlines are 10% ink. Small
   radii (4px buttons/cards, 8px media frames via rounded-xl). Dark bands on the light page
   carry the `dark` class and use the .dark values below. */
:root {
  --background: #f2f6fa;
  --foreground: #162029;
  --card: #ffffff;
  --card-foreground: #162029;
  --popover: #ffffff;
  --popover-foreground: #162029;
  --primary: #acff24;
  --primary-foreground: #162029;
  --secondary: #d8e4eb;
  --secondary-foreground: #162029;
  --muted: #d8e4eb;
  --muted-foreground: rgb(22 32 41 / 0.6);
  --accent: rgb(22 32 41 / 0.05);
  --accent-foreground: #162029;
  --destructive: #d8432a;
  --destructive-foreground: #ffffff;
  --border: rgb(22 32 41 / 0.1);
  --input: rgb(22 32 41 / 0.2);
  --ring: #162029;
  --highlight: #fb6b3c;
  --highlight-foreground: #162029;
  --glow: #89a2b0;
  --chart-1: #acff24;
  --chart-2: #1d4d68;
  --chart-3: #89a2b0;
  --chart-4: #fb6b3c;
  --chart-5: #79848f;
  --sidebar: #f2f6fa;
  --sidebar-foreground: #162029;
  --sidebar-primary: #acff24;
  --sidebar-primary-foreground: #162029;
  --sidebar-accent: #d8e4eb;
  --sidebar-accent-foreground: #162029;
  --sidebar-border: rgb(22 32 41 / 0.1);
  --sidebar-ring: #162029;

  --typeface-body: "Host Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Host Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "Source Code Pro Variable", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.25rem;
  --page-width: 80rem;
  --page-gutter: 1rem;
  --section-y: 5rem;
}

/* Dark: the original's slate bands. Slate #44505c ground ("midnight200"), steel-white text,
   the ink #162029 as the card (the footer's ground), 20% white hairlines, 50% white quiet
   text, the same lime. Used for the whole page in dark mode and for every `dark` band. */
.dark {
  --background: #44505c;
  --foreground: #f2f6fa;
  --card: #162029;
  --card-foreground: #f2f6fa;
  --popover: #0f161c;
  --popover-foreground: #f2f6fa;
  --primary: #acff24;
  --primary-foreground: #162029;
  --secondary: rgb(242 246 250 / 0.14);
  --secondary-foreground: #f2f6fa;
  --muted: #5a6672;
  --muted-foreground: rgb(242 246 250 / 0.5);
  --accent: rgb(242 246 250 / 0.05);
  --accent-foreground: #f2f6fa;
  --destructive: #fb6b3c;
  --destructive-foreground: #162029;
  --border: rgb(242 246 250 / 0.2);
  --input: rgb(242 246 250 / 0.2);
  --ring: #acff24;
  --highlight: #fb6b3c;
  --highlight-foreground: #162029;
  --glow: #89a2b0;
  --chart-1: #acff24;
  --chart-2: #89a2b0;
  --chart-3: #afc2cc;
  --chart-4: #fb6b3c;
  --chart-5: #d8e4eb;
  --sidebar: #162029;
  --sidebar-foreground: #f2f6fa;
  --sidebar-primary: #acff24;
  --sidebar-primary-foreground: #162029;
  --sidebar-accent: rgb(242 246 250 / 0.05);
  --sidebar-accent-foreground: #f2f6fa;
  --sidebar-border: rgb(242 246 250 / 0.2);
  --sidebar-ring: #acff24;
}
